    def __init__(self, brand, speed, battery_kwh):
        super().__init__(brand, speed)
        self.battery_kwh = battery_kwh

    def describe(self):
        base_desc = super().describe()
        return f"{base_desc} with {self.battery_kwh}kWh Battery"

