def divide_safe(a, b):
    try:
        result = a / b
    except ZeroDivisionError as e:
        print(f"Caught Division by Zero Error: {e}")
        return None
    else:
        print("Division calculated successfully without errors!")
        return result
    finally:
        print("Cleanup operations completed.")

divide_safe(10, 2)
divide_safe(10, 0)

